from pathlib import Path

path = Path("index.html")
text = path.read_text(encoding="utf-8")
marker = "BEGIN EcologicaLite BEST SCORE + reproduction visual feature"
if marker in text:
    raise SystemExit("feature marker already present")
anchor = "try {base=await loadConfig();images=await loadImages(assetSources);initializeUi();setResponsiveLayout();bindAbilityTips();"
if text.count(anchor) != 1:
    raise SystemExit(f"expected one UI startup anchor, found {text.count(anchor)}")
feature = '/* BEGIN EcologicaLite BEST SCORE + reproduction visual feature */\nconst BEST_SCORE_VERSION=\'v1r-score-1\';\nconst BEST_STORAGE_KEY=`ecologicalite.bestRuns.${BEST_SCORE_VERSION}`;\nconst BEST_LIMIT=5;\nconst REPRO_FX_MS=400;\nlet bestScoreOverlay=null;\nlet currentNewRecord=null;\nlet reproFx=[];\nlet reproFxRaf=0;\nlet resultSnapshotMode=\'current\';\n\nconst safeBestRead=()=>{\n  try{\n    const parsed=JSON.parse(localStorage.getItem(BEST_STORAGE_KEY)||\'[]\');\n    return Array.isArray(parsed)?parsed.filter(x=>x&&Number.isFinite(Number(x.score))).slice(0,BEST_LIMIT):[];\n  }catch(_error){return [];}\n};\nconst safeBestWrite=list=>{\n  try{localStorage.setItem(BEST_STORAGE_KEY,JSON.stringify(list.slice(0,BEST_LIMIT)));return true;}\n  catch(_error){return false;}\n};\nconst safeBestClear=()=>{\n  try{localStorage.removeItem(BEST_STORAGE_KEY);return true;}\n  catch(_error){return false;}\n};\nconst compactDate=iso=>{\n  const d=new Date(iso);if(Number.isNaN(d.getTime()))return \'—\';\n  const pad=n=>String(n).padStart(2,\'0\');\n  return `${d.getFullYear()}/${pad(d.getMonth()+1)}/${pad(d.getDate())} ${pad(d.getHours())}:${pad(d.getMinutes())}`;\n};\nconst snapshotScoreKeys=[\n  [\'herbFeed\',\'植物摂食\'],[\'carnPred\',\'捕食\'],[\'herbBirth\',\'草食出生\'],\n  [\'carnBirth\',\'肉食出生\'],[\'herbSurvival\',\'草食生存\'],[\'carnSurvival\',\'肉食生存\']\n];\nfunction buildRunSnapshot(s){\n  const results=s.results||[];\n  const sumEvent=key=>results.reduce((n,r)=>n+Number(r.events?.[key]||0),0);\n  const sumScore=key=>results.reduce((n,r)=>n+Number(r.score?.components?.[key]||0),0);\n  const selections=(s.selectionHistory||[]).filter(e=>e?.selected).map(e=>({\n    type:e.type,set:e.set,stage:e.stage,id:e.selected.id,name:e.selected.name\n  }));\n  const normalMap=new Map();\n  for(const e of selections.filter(x=>x.type===\'normal\')){\n    const prev=normalMap.get(e.id)||{id:e.id,name:e.name,count:0};prev.count++;normalMap.set(e.id,prev);\n  }\n  const stages=results.map(r=>({\n    set:Number(r.set),stage:Number(r.stage),\n    plants:Number(r.counts?.plants||0),herbs:Number(r.counts?.herbs||0),carns:Number(r.counts?.carns||0),\n    score:Number(r.score?.total||0)\n  }));\n  const score=Number(s.runScore());\n  const fingerprint=JSON.stringify({\n    seed:String(s.seed),\n    selections:selections.map(e=>e.id),\n    score,\n    stages:stages.map(r=>[r.set,r.stage,r.plants,r.herbs,r.carns,r.score])\n  });\n  return {\n    schema:1,scoreVersion:BEST_SCORE_VERSION,score,\n    setScores:[1,2].map(set=>results.filter(r=>r.set===set).reduce((n,r)=>n+Number(r.score?.total||0),0)),\n    scoreComponents:Object.fromEntries(snapshotScoreKeys.map(([key])=>[key,sumScore(key)])),\n    ecology:{\n      plantEaten:sumEvent(\'plantEaten\'),herbEaten:sumEvent(\'herbEaten\'),\n      herbBirths:sumEvent(\'herbBirths\'),carnBirths:sumEvent(\'carnBirths\'),\n      herbNaturalDeaths:sumEvent(\'herbNaturalDeaths\'),carnNaturalDeaths:sumEvent(\'carnNaturalDeaths\')\n    },\n    setAbilities:selections.filter(e=>e.type===\'set\').map(e=>({set:e.set,id:e.id,name:e.name})),\n    normalAbilities:[...normalMap.values()],\n    stages,\n    seed:String(s.seed),\n    completedAt:s.runMeta?.endedAt||new Date().toISOString(),\n    fingerprint\n  };\n}\nfunction storeBestSnapshot(record){\n  const list=safeBestRead(),existing=list.findIndex(x=>x.fingerprint===record.fingerprint);\n  if(existing>=0)return {rank:existing+1,isNew:false,list};\n  let index=list.findIndex(x=>Number(record.score)>Number(x.score));\n  if(index<0)index=list.length;\n  if(index>=BEST_LIMIT)return {rank:null,isNew:false,list};\n  list.splice(index,0,record);const next=list.slice(0,BEST_LIMIT);\n  if(!safeBestWrite(next))return {rank:null,isNew:false,list};\n  return {rank:index+1,isNew:true,list:next};\n}\nconst resultCard=()=>document.querySelector(\'#result>.result-card\');\nconst clearDetailBack=()=>document.getElementById(\'best-detail-back\')?.remove();\nfunction addDetailBack(){\n  clearDetailBack();\n  const b=document.createElement(\'button\');b.id=\'best-detail-back\';b.type=\'button\';b.textContent=\'GAME SETへ戻る\';\n  b.onclick=()=>showCurrentRunDetail();resultCard()?.append(b);\n}\nfunction makeKV(parent,key,value){\n  const row=document.createElement(\'div\');row.className=\'run-kv\';\n  const a=document.createElement(\'span\');a.textContent=key;const b=document.createElement(\'strong\');b.textContent=value;\n  row.append(a,b);parent.append(row);return row;\n}\nfunction detailSection(title,className=\'\'){\n  const s=document.createElement(\'section\');s.className=`run-detail-section ${className}`.trim();\n  const h=document.createElement(\'h3\');h.textContent=title;s.append(h);return s;\n}\nfunction renderSnapshotDetail(record,{saved=false,rank=null}={}){\n  const root=$(\'result-details\');if(!root||!record)return;\n  root.className=\'result-detail-groups run-detail-layout\';root.replaceChildren();\n  const overview=detailSection(\'得点・生態系\',\'run-detail-overview\');\n  const scoreGrid=document.createElement(\'div\');scoreGrid.className=\'run-score-grid\';\n  for(const [key,labelText] of snapshotScoreKeys)makeKV(scoreGrid,labelText,formatScore(record.scoreComponents?.[key]||0));\n  overview.append(scoreGrid);\n  const ecoGrid=document.createElement(\'div\');ecoGrid.className=\'run-eco-grid\';\n  makeKV(ecoGrid,\'植物摂食\',int(record.ecology?.plantEaten||0));\n  makeKV(ecoGrid,\'捕食\',int(record.ecology?.herbEaten||0));\n  makeKV(ecoGrid,\'草食出生\',int(record.ecology?.herbBirths||0));\n  makeKV(ecoGrid,\'肉食出生\',int(record.ecology?.carnBirths||0));\n  makeKV(ecoGrid,\'草食死亡\',`自然 ${int(record.ecology?.herbNaturalDeaths||0)} / 捕食 ${int(record.ecology?.herbEaten||0)}`);\n  makeKV(ecoGrid,\'肉食死亡\',int(record.ecology?.carnNaturalDeaths||0));\n  overview.append(ecoGrid);\n\n  const abilities=detailSection(\'取得能力\',\'run-detail-abilities\');\n  const setGrid=document.createElement(\'div\');setGrid.className=\'run-set-grid\';\n  for(let set=1;set<=2;set++){\n    const a=record.setAbilities?.find(x=>Number(x.set)===set);\n    const card=document.createElement(\'div\');card.className=\'run-ability-card set\';\n    card.innerHTML=`<small>SET ${set}</small><strong>${a?.name||\'—\'}</strong>`;setGrid.append(card);\n  }\n  abilities.append(setGrid);\n  const normalGrid=document.createElement(\'div\');normalGrid.className=\'run-normal-grid\';\n  for(const a of record.normalAbilities||[]){\n    const item=document.createElement(\'div\');item.className=\'run-ability-card normal\';\n    item.innerHTML=`<span>${a.name}</span><strong>×${a.count}</strong>`;normalGrid.append(item);\n  }\n  if(!normalGrid.childElementCount){const empty=document.createElement(\'span\');empty.className=\'run-empty\';empty.textContent=\'通常能力なし\';normalGrid.append(empty);}\n  abilities.append(normalGrid);\n\n  const stages=detailSection(\'STAGE結果\',\'run-detail-stages\');\n  const stageGrid=document.createElement(\'div\');stageGrid.className=\'run-stage-grid\';\n  for(let set=1;set<=2;set++){\n    const wrap=document.createElement(\'div\');wrap.className=\'run-stage-set\';\n    const head=document.createElement(\'div\');head.className=\'run-stage-set-head\';\n    head.innerHTML=`<span>SET ${set}</span>`;wrap.append(head);\n    const table=document.createElement(\'table\');table.className=\'run-stage-table\';\n    table.innerHTML=\'<thead><tr><th>S</th><th>植</th><th>草</th><th>肉</th><th>得点</th></tr></thead><tbody></tbody>\';\n    const body=table.querySelector(\'tbody\');\n    for(const r of (record.stages||[]).filter(x=>Number(x.set)===set)){\n      const tr=document.createElement(\'tr\');\n      tr.innerHTML=`<th>${r.stage}</th><td>${int(r.plants)}</td><td>${int(r.herbs)}</td><td>${int(r.carns)}</td><td>${formatScore(r.score)}</td>`;body.append(tr);\n    }\n    wrap.append(table);stageGrid.append(wrap);\n  }\n  stages.append(stageGrid);\n\n  if(saved){\n    const meta=detailSection(\'記録\',\'run-detail-meta\');\n    const grid=document.createElement(\'div\');grid.className=\'run-meta-grid\';\n    makeKV(grid,\'順位\',`#${rank||\'—\'}`);\n    makeKV(grid,\'日時\',compactDate(record.completedAt));\n    makeKV(grid,\'seed\',record.seed||\'—\').classList.add(\'run-meta-seed\');\n    meta.append(grid);root.append(meta);\n  }\n  root.append(overview,abilities,stages);\n}\nfunction applyResultHeader(record,{saved=false,rank=null}={}){\n  $(\'final-score\').textContent=formatScore(record.score);\n  $(\'final-set1\').textContent=formatScore(record.setScores?.[0]||0);\n  $(\'final-set2\').textContent=formatScore(record.setScores?.[1]||0);\n  const heading=$(\'result-heading\');\n  if(saved){\n    resultSnapshotMode=\'saved\';heading.classList.add(\'best-detail-heading\');heading.dataset.displayHeading=`BEST #${rank}`;\n    heading.setAttribute(\'aria-label\',`BEST #${rank}`);\n  }else{\n    resultSnapshotMode=\'current\';heading.classList.remove(\'best-detail-heading\');delete heading.dataset.displayHeading;heading.setAttribute(\'aria-label\',\'GAME SET\');\n  }\n}\nfunction showSavedRunDetail(record,rank){\n  applyResultHeader(record,{saved:true,rank});renderSnapshotDetail(record,{saved:true,rank});\n  const details=resultCard()?.querySelector(\'details\');if(details)details.open=true;\n  addDetailBack();\n}\nfunction showCurrentRunDetail(){\n  if(!session?.runDone)return;const record=buildRunSnapshot(session);\n  applyResultHeader(record);renderSnapshotDetail(record);clearDetailBack();\n}\nrenderResultDetails=function(){showCurrentRunDetail();};\n\nfunction ensureBestOverlay(){\n  if(bestScoreOverlay)return bestScoreOverlay;\n  const overlay=document.createElement(\'div\');overlay.id=\'best-score-overlay\';overlay.hidden=true;\n  overlay.innerHTML=\'<div class="best-shade best-shade-graph"></div><div class="best-shade best-shade-abilities"></div><div class="best-score-card"><div class="best-score-head"><strong>BEST SCORE</strong><span id="best-new-record"></span></div><div id="best-score-list" class="best-score-list"></div></div>\';\n  document.body.append(overlay);bestScoreOverlay=overlay;return overlay;\n}\nfunction positionBestOverlay(){\n  const overlay=ensureBestOverlay(),graph=$(\'score-panel\'),abilities=document.querySelector(\'.abilities-panel\');\n  if(overlay.hidden||!graph||!abilities)return;\n  const gr=graph.getBoundingClientRect(),ar=abilities.getBoundingClientRect(),graphShade=overlay.querySelector(\'.best-shade-graph\'),abilityShade=overlay.querySelector(\'.best-shade-abilities\'),card=overlay.querySelector(\'.best-score-card\');\n  const place=(el,r)=>{el.style.left=`${r.left}px`;el.style.top=`${r.top}px`;el.style.width=`${r.width}px`;el.style.height=`${r.height}px`;};\n  place(graphShade,gr);place(abilityShade,ar);\n  if(desktopQuery.matches){\n    card.style.left=`${gr.left}px`;card.style.top=`${gr.top}px`;card.style.width=`${gr.width}px`;card.style.height=`${Math.min(gr.height,ar.height)}px`;\n  }else{\n    const left=Math.min(gr.left,ar.left),top=Math.min(gr.top,ar.top),right=Math.max(gr.right,ar.right),bottom=Math.min(gr.bottom,ar.bottom);\n    card.style.left=`${left}px`;card.style.top=`${top}px`;card.style.width=`${right-left}px`;card.style.height=`${Math.max(0,bottom-top)}px`;\n  }\n}\nfunction renderBestScores(newRecord=null){\n  const overlay=ensureBestOverlay(),list=safeBestRead(),root=$(\'best-score-list\'),tag=$(\'best-new-record\');\n  root.replaceChildren();tag.textContent=newRecord?.isNew?`NEW RECORD #${newRecord.rank}`:\'\';\n  if(!list.length){\n    const empty=document.createElement(\'div\');empty.className=\'best-empty\';empty.textContent=\'記録はまだありません\';root.append(empty);\n  }else list.forEach((record,index)=>{\n    const row=document.createElement(\'button\');row.type=\'button\';row.className=\'best-score-row\';\n    if(newRecord?.isNew&&newRecord.rank===index+1)row.classList.add(\'new-record\');\n    row.innerHTML=`<span class="best-rank">${index+1}</span><strong>${formatScore(record.score)}</strong><small>詳細</small>`;\n    row.onclick=()=>showSavedRunDetail(record,index+1);root.append(row);\n  });\n  overlay.hidden=false;requestAnimationFrame(positionBestOverlay);\n}\nfunction hideBestScores(){const overlay=ensureBestOverlay();overlay.hidden=true;}\nfunction installBestReset(){\n  const scoreDetails=[...document.querySelectorAll(\'.info-tier\')].find(s=>s.querySelector(\'.info-tier-head h2\')?.textContent.trim()===\'詳細データ\');\n  if(!scoreDetails||document.getElementById(\'best-score-reset\'))return;\n  const details=document.createElement(\'details\');details.className=\'info-details\';\n  details.innerHTML=\'<summary>記録</summary><div class="info-content"><div class="info-sub"><h3>BEST SCORE</h3><p>このブラウザ・端末に上位5件を保存します。</p><button id="best-score-reset" type="button" class="best-score-reset">BEST SCOREを削除</button></div></div>\';\n  scoreDetails.append(details);\n  $(\'best-score-reset\').onclick=()=>{\n    if(!window.confirm(\'BEST SCOREの記録5件を削除します。元に戻せません。\'))return;\n    safeBestClear();currentNewRecord=null;if(session?.runDone)renderBestScores(null);\n  };\n}\nfunction recordCompletedRun(){\n  if(!session?.runDone)return null;\n  const outcome=storeBestSnapshot(buildRunSnapshot(session));currentNewRecord=outcome;\n  renderBestScores(outcome);return outcome;\n}\n\nfunction requestReproductionPaint(){\n  if(reproFxRaf)return;\n  const tick=()=>{\n    reproFxRaf=0;\n    if(!reproFx.length)return;\n    paint();\n    if(reproFx.length)reproFxRaf=requestAnimationFrame(tick);\n  };\n  reproFxRaf=requestAnimationFrame(tick);\n}\nfunction onReproductionEvent(_world,event){\n  if(!event||!event.actor||!event.childId)return;\n  const childIds=[event.childId,...(event.extraChildIds||[])].filter(Boolean);\n  reproFx.push({\n    type:event.actor.type,parentId:event.actor.id,childIds,\n    x:Number(event.actor.x),y:Number(event.actor.y),startedAt:performance.now()\n  });\n  if(reproFx.length>48)reproFx=reproFx.slice(-48);\n  requestReproductionPaint();\n}\nfunction installReproductionObserver(){\n  if(!session?.world)return;\n  const world=session.world,prior=(typeof world.observer===\'function\'&&!world.observer.__ecologicaRepro)?world.observer:null;\n  const observer=(w,event)=>{if(prior)prior(w,event);onReproductionEvent(w,event);};\n  observer.__ecologicaRepro=true;\n  Object.defineProperty(world,\'observer\',{value:observer,writable:true,configurable:true,enumerable:false});\n}\nfunction drawReproductionFx(){\n  if(!session||!reproFx.length)return;\n  const now=performance.now();reproFx=reproFx.filter(fx=>now-fx.startedAt<REPRO_FX_MS);if(!reproFx.length)return;\n  const canvas=$(\'field\'),ctx=canvas.getContext(\'2d\'),cfg=session.cfg,dpr=Math.min(2,window.devicePixelRatio||1),cssW=canvas.clientWidth||700,cssH=cssW*cfg.rows/cfg.cols;\n  const cell=Math.min(cssW/cfg.cols,cssH/cfg.rows),ox=(cssW-cell*cfg.cols)/2,oy=(cssH-cell*cfg.rows)/2;\n  ctx.save();ctx.setTransform(dpr,0,0,dpr,0,0);\n  for(const fx of reproFx){\n    const t=Math.max(0,Math.min(1,(now-fx.startedAt)/REPRO_FX_MS)),cx=ox+(fx.x+.5)*cell,cy=oy+(fx.y+.5)*cell;\n    ctx.beginPath();ctx.arc(cx,cy,cell*(.42+2.2*t),0,Math.PI*2);ctx.strokeStyle=`rgba(245,250,255,${.7*(1-t)})`;ctx.lineWidth=Math.max(1,cell*.065);ctx.stroke();\n    const ids=new Set([fx.parentId,...fx.childIds]);\n    const flashes=drawn.filter(d=>ids.has(d.id));\n    for(const d of flashes){\n      ctx.save();ctx.globalAlpha=.72*(1-t);ctx.globalCompositeOperation=\'screen\';ctx.filter=\'brightness(2.5) saturate(.2)\';\n      ctx.drawImage(images[d.type],d.rect.x,d.rect.y,d.rect.w,d.rect.h);ctx.restore();\n    }\n  }\n  ctx.restore();\n}\n\nconst legacyInitializeUi=initializeUi;\ninitializeUi=function(){\n  legacyInitializeUi();installBestReset();ensureBestOverlay();\n};\nconst legacyChoose=choose;\nchoose=function(){hideBestScores();currentNewRecord=null;clearDetailBack();return legacyChoose();};\nconst legacyRunStage=runStage;\nrunStage=function(){\n  hideBestScores();reproFx=[];if(reproFxRaf){cancelAnimationFrame(reproFxRaf);reproFxRaf=0;}legacyRunStage();installReproductionObserver();\n};\nconst legacyPaint=paint;\npaint=function(){legacyPaint();drawReproductionFx();};\nconst legacyFinish=finish;\nfinish=function(){\n  legacyFinish();\n  if(session?.runDone){recordCompletedRun();positionBestOverlay();}\n};\nconst featureResize=()=>requestAnimationFrame(()=>{if(session?.runDone&&!ensureBestOverlay().hidden)positionBestOverlay();});\nwindow.addEventListener(\'resize\',featureResize);\n\nconst featureStyle=document.createElement(\'style\');\nfeatureStyle.id=\'best-score-repro-feature-styles\';\nfeatureStyle.textContent=`\n#best-score-overlay[hidden]{display:none!important}\n#best-score-overlay{position:fixed;inset:0;z-index:70;pointer-events:none}\n.best-shade{position:fixed;border-radius:10px;background:rgba(3,8,13,.54);backdrop-filter:blur(1.7px);-webkit-backdrop-filter:blur(1.7px);pointer-events:none}\n.best-score-card{position:fixed;z-index:2;padding:8px;border:1px solid rgba(91,116,141,.72);border-radius:10px;background:rgba(13,22,32,.91);box-shadow:0 12px 30px rgba(0,0,0,.3);pointer-events:auto;overflow:auto}\n.best-score-head{display:flex;align-items:baseline;justify-content:space-between;gap:6px;margin-bottom:5px;color:#e8d089}.best-score-head strong{font-size:10px;letter-spacing:.08em}.best-score-head span{font-size:7px;color:#99d9bf;font-weight:800;white-space:nowrap}\n.best-score-list{display:grid;gap:4px}.best-score-row{width:100%;min-height:29px;padding:3px 6px;display:grid;grid-template-columns:18px minmax(0,1fr) auto;gap:5px;align-items:center;border:1px solid rgba(64,86,111,.75);border-radius:7px;background:rgba(21,35,53,.92);text-align:left}\n.best-score-row .best-rank{color:#8295a9;font-size:8px;font-weight:800}.best-score-row strong{text-align:right;color:#edf4fb;font-size:13px;font-variant-numeric:tabular-nums}.best-score-row small{color:#99d9bf;font-size:7px}.best-score-row.new-record{border-color:#91cdb7;box-shadow:inset 0 0 0 1px rgba(153,217,191,.18)}\n.best-empty{padding:18px 6px;color:#8fa2b5;font-size:9px;text-align:center}\n#result-heading.best-detail-heading::after{content:attr(data-display-heading)!important}\n.result-panel.result-overlay-panel .result-card{width:min(96%,680px)!important}\n#result-details.run-detail-layout{display:grid!important;grid-template-columns:minmax(0,1fr) minmax(0,1fr)!important;gap:7px!important;margin:6px 0 2px!important}\n.run-detail-section{min-width:0;padding:7px;border:1px solid rgba(93,117,141,.26);border-radius:8px;background:rgba(9,16,24,.36)}.run-detail-section>h3{margin:0 0 5px;color:#edf4fb;font-size:9.5px}.run-detail-stages{grid-column:1/-1}.run-detail-meta{grid-column:1/-1}\n.run-score-grid,.run-eco-grid,.run-meta-grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:2px 8px}.run-meta-seed{grid-column:1/-1}.run-eco-grid{margin-top:5px;padding-top:5px;border-top:1px solid rgba(93,117,141,.2)}\n.run-kv{min-width:0;display:flex;justify-content:space-between;gap:5px;padding:2px 0;align-items:baseline}.run-kv span{min-width:0;color:#8fa2b5;font-size:7.5px}.run-kv strong{color:#e3edf6;font-size:8px;text-align:right;font-weight:650;font-variant-numeric:tabular-nums;overflow-wrap:anywhere}\n.run-set-grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:4px}.run-normal-grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:3px;margin-top:4px}\n.run-ability-card{min-width:0;border-radius:6px}.run-ability-card.set{padding:5px;border:1px solid #8f7940;background:rgba(91,77,32,.46)}.run-ability-card.set small{display:block;color:#b5a777;font-size:6.5px}.run-ability-card.set strong{display:block;margin-top:2px;color:#ffe89b;font-size:7.5px;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}\n.run-ability-card.normal{display:grid;grid-template-columns:minmax(0,1fr) auto;gap:4px;padding:4px 5px;border:1px solid rgba(64,86,111,.76);background:rgba(21,35,53,.65)}.run-ability-card.normal span{min-width:0;color:#cbd7e4;font-size:7px;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}.run-ability-card.normal strong{color:#99d9bf;font-size:7px}.run-empty{color:#8295a9;font-size:7px}\n.run-stage-grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:6px}.run-stage-set{min-width:0}.run-stage-set-head{display:flex;justify-content:space-between;align-items:baseline;margin-bottom:2px;color:#e8d089;font-size:7.5px}.run-stage-table{width:100%;border-collapse:collapse;table-layout:fixed;font-variant-numeric:tabular-nums}.run-stage-table th,.run-stage-table td{padding:2px 2px;border-bottom:1px solid rgba(93,117,141,.16);font-size:7px;text-align:right;white-space:nowrap}.run-stage-table th:first-child,.run-stage-table td:first-child{text-align:left}.run-stage-table thead th{color:#7f92a6;font-size:6.5px;font-weight:650}.run-stage-table tbody th{color:#e8d089;font-weight:650}\n#best-detail-back{width:100%;height:28px;margin-top:6px;padding:0 8px;border-radius:999px;font-size:8px;line-height:26px;background:#152335}\n.best-score-reset{width:100%;margin-top:5px;padding:8px 10px;border-color:#80535c;background:#2a1d23;color:#e9cbd2;font-size:10px}\n@media(max-width:639px){\n  .result-panel.result-overlay-panel .result-card{width:100%!important;padding:8px!important}\n  #result-details.run-detail-layout{grid-template-columns:1fr!important;gap:5px!important}\n  .run-detail-stages,.run-detail-meta{grid-column:auto}.run-detail-section{padding:6px}\n  .run-score-grid,.run-eco-grid,.run-meta-grid{grid-template-columns:repeat(2,minmax(0,1fr))}\n  .run-stage-grid{grid-template-columns:repeat(2,minmax(0,1fr));gap:4px}\n  .run-stage-table th,.run-stage-table td{padding:2px 1px;font-size:6.5px}.run-stage-table thead th{font-size:6px}\n  .best-score-card{padding:7px}.best-score-row{min-height:31px}.best-score-row strong{font-size:14px}\n}\n@media(max-width:390px){\n  .run-kv span{font-size:7px}.run-kv strong{font-size:7.5px}.run-ability-card.set strong{font-size:7px}.run-ability-card.normal span,.run-ability-card.normal strong{font-size:6.5px}\n  .run-stage-table th,.run-stage-table td{font-size:6px}.run-stage-table thead th{font-size:5.7px}\n}\n`;\ndocument.head.append(featureStyle);\n/* END EcologicaLite BEST SCORE + reproduction visual feature */\n'
